function categorizeInput(desc) {
  const d = desc.toLowerCase();
  if (d.includes('ketik') || d.includes('pin') || d.includes('pembelian') || d.includes('keyboard') || d.includes('atm') || d.includes('pos')) return 'peranti pengetikan';
  if (d.includes('klik') || d.includes('kursor') || d.includes('mouse') || d.includes('touch') || d.includes('trackball') || d.includes('joystick') || d.includes('pena') || d.includes('digitizing tablet')) return 'peranti penunjuk';
  if (d.includes('barcode') || d.includes('micr') || d.includes('omr') || d.includes('ocr') || d.includes('pindai') || d.includes('gambar') || d.includes('dokumen')) return 'pengambil gambar terformat';
  return 'tidak yakin';
}

const samples = [
  'Memasukkan PIN pada ATM',
  'Menggerakkan mouse untuk memilih menu di layar',
  'Memfoto dokumen lalu diubah jadi teks (OCR)',
  'Memindai barcode untuk tahu harga'
];

for (const s of samples) {
  console.log(s + ' => ' + categorizeInput(s));
}

function pickTech(desc) {
  const d = desc.toLowerCase();
  if (d.includes('barcode') || d.includes('kode batang') || d.includes('garis hitam')) return 'Barcode Reader';
  if (d.includes('cek') || d.includes('bilyet') || d.includes('tinta magnetic') || d.includes('micr')) return 'MICR';
  if (d.includes('lembar jawaban') || d.includes('tanda') || d.includes('bulatan') || d.includes('omr')) return 'OMR';
  if (d.includes('teks') || d.includes('dokumen') || d.includes('foto') || d.includes('dapat diedit') || d.includes('ocr')) return 'OCR';
  return 'Belum bisa ditentukan';
}

const tests = [
  'Scanner membaca pola garis hitam-putih pada kode batang untuk harga',
  'Perbankan membaca karakter khusus pada cek menggunakan tinta magnetic',
  'Membaca tanda bulatan di lembar jawaban ujian untuk menilai',
  'Mengubah foto dokumen berisi teks menjadi teks yang bisa dicari dan disunting'
];

for (const t of tests) {
  console.log(t + ' => ' + pickTech(t));
}
